CREATE TEMP TABLE _delta_people_ids ON COMMIT DROP AS
SELECT incoming.id AS local_id, COALESCE(existing.id, incoming.id) AS target_id
FROM _delta_people incoming
LEFT JOIN public.people existing ON existing.external_id = incoming.external_id;

CREATE TEMP TABLE _delta_candidate_ids ON COMMIT DROP AS
SELECT incoming.id AS local_id, COALESCE(existing.id, incoming.id) AS target_id
FROM _delta_candidates incoming
LEFT JOIN public.candidates existing ON existing.external_id = incoming.external_id;

UPDATE _delta_candidates incoming
SET person_id = COALESCE(existing.id, person_key.target_id)
FROM _delta_person_keys person_key
LEFT JOIN public.people existing ON existing.external_id = person_key.external_id
WHERE incoming.person_id = person_key.local_id;

UPDATE _delta_candidates incoming
SET race_id = existing.id
FROM _delta_race_keys race_key
JOIN public.races existing ON existing.external_id = race_key.external_id
WHERE incoming.race_id = race_key.local_id;

UPDATE _delta_claims incoming
SET person_id = COALESCE(existing.id, person_key.target_id)
FROM _delta_person_keys person_key
LEFT JOIN public.people existing ON existing.external_id = person_key.external_id
WHERE incoming.person_id = person_key.local_id;

UPDATE _delta_people incoming SET id = ids.target_id FROM _delta_people_ids ids WHERE incoming.id = ids.local_id;
UPDATE _delta_candidates incoming SET id = ids.target_id FROM _delta_candidate_ids ids WHERE incoming.id = ids.local_id;
UPDATE _delta_candidates SET updated_at = NOW();

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM _delta_people) <> 2 OR (SELECT COUNT(*) FROM _delta_candidates) <> 15 OR (SELECT COUNT(*) FROM _delta_claims) <> 2 THEN
        RAISE EXCEPTION 'Production public identity delta count drift';
    END IF;
    IF EXISTS (SELECT 1 FROM _delta_candidates candidate LEFT JOIN public.people person ON person.id = candidate.person_id WHERE person.id IS NULL AND NOT EXISTS (SELECT 1 FROM _delta_people incoming_person WHERE incoming_person.id = candidate.person_id))
       OR EXISTS (SELECT 1 FROM _delta_candidates candidate LEFT JOIN public.races race ON race.id = candidate.race_id WHERE race.id IS NULL)
       OR EXISTS (SELECT 1 FROM _delta_claims claim LEFT JOIN public.people person ON person.id = claim.person_id WHERE person.id IS NULL AND NOT EXISTS (SELECT 1 FROM _delta_people incoming_person WHERE incoming_person.id = claim.person_id)) THEN
        RAISE EXCEPTION 'Production public identity delta is missing a prerequisite person or race';
    END IF;
    IF EXISTS (SELECT 1 FROM public.people existing JOIN _delta_people incoming ON existing.id = incoming.id WHERE existing.external_id IS DISTINCT FROM incoming.external_id)
       OR EXISTS (SELECT 1 FROM public.candidates existing JOIN _delta_candidates incoming ON existing.id = incoming.id WHERE existing.external_id IS DISTINCT FROM incoming.external_id)
       OR EXISTS (SELECT 1 FROM public.person_claims existing JOIN _delta_claims incoming ON existing.claim_key = incoming.claim_key WHERE existing.id <> incoming.id) THEN
        RAISE EXCEPTION 'Production public identity delta identifier conflict';
    END IF;
END
$$;

INSERT INTO public.people (id, name, alias, party, position, election_year, district, source_url, is_public, created_at, updated_at, external_id, gender, education, experience)
SELECT id, name, alias, party, position, election_year, district, source_url, is_public, created_at, updated_at, external_id, gender, education, experience FROM _delta_people
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    alias = EXCLUDED.alias,
    party = EXCLUDED.party,
    position = EXCLUDED.position,
    election_year = EXCLUDED.election_year,
    district = EXCLUDED.district,
    source_url = EXCLUDED.source_url,
    is_public = EXCLUDED.is_public,
    updated_at = EXCLUDED.updated_at,
    external_id = EXCLUDED.external_id,
    gender = EXCLUDED.gender,
    education = EXCLUDED.education,
    experience = EXCLUDED.experience;

