SELECT id, claim_key, person_id, source_person_id, claim_type, claim_value, claim_json, confidence_level, review_status, visibility, source_name, source_url, observed_at, is_public, created_at, updated_at, review_score, scoring_version, scoring_reasons, auto_reviewed_at, candidate_id FROM _delta_claims
