SELECT public.refresh_public_people_list_cached();
SELECT published.promote(NULL);

DO $$
DECLARE
    published_people_count INTEGER;
    published_candidate_count INTEGER;
    published_fact_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO published_people_count FROM published.people item JOIN _delta_people release ON release.id = item.person_id;
    SELECT COUNT(*) INTO published_candidate_count FROM published.candidates item JOIN _delta_candidates release ON release.id = item.candidate_id;
    SELECT COUNT(*) INTO published_fact_count FROM published.candidate_facts item JOIN _delta_candidates release ON release.id = item.candidate_id;
    IF published_people_count <> 2 OR published_candidate_count <> 15 OR published_fact_count <> 15 THEN
        RAISE EXCEPTION 'Production public identity delta publication verification failed: people %, candidates %, facts %', published_people_count, published_candidate_count, published_fact_count;
    END IF;
END
$$;

COMMIT;
